import{_ as o,o as r,c as s,j as e,a as t}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"事件委托是什么？","description":"事件委托本质上是利用了浏览器事件冒泡的机制。因为事件在冒泡过程中会上传到父节点，并且父节点可以通过事件对象获取到目标节点，因此可以把子节点的监听函数定义在父节点上，由父节点的监听函数统一处理多个子元素的事件，这种方式称为事件 代理。 使用事件代理我们可以不必要为每一个子元素都绑定。","frontmatter":{"title":"事件委托是什么？","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"事件委托本质上是利用了浏览器事件冒泡的机制。因为事件在冒泡过程中会上传到父节点，并且父节点可以通过事件对象获取到目标节点，因此可以把子节点的监听函数定义在父节点上，由父节点的监听函数统一处理多个子元素的事件，这种方式称为事件 代理。 使用事件代理我们可以不必要为每一个子元素都绑定。","sidebarWeight":48,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/DOM/事件/事件委托是什么？.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/事件/事件委托是什么？.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/事件/事件委托是什么？.md"}'),n={name:"posts/JavaScript系统教程/04-浏览器与 Web API/事件/事件委托是什么？.md"};function i(c,a,l,p,d,b){return r(),s("div",null,[...a[0]||(a[0]=[e("div",null,[e("h1",{id:"事件委托是什么",tabindex:"-1"},[t("事件委托是什么？ "),e("a",{class:"header-anchor",href:"#事件委托是什么","aria-label":'Permalink to "事件委托是什么？"'},"​")]),e("blockquote",null,[e("p",null,[t("本节目标：理解“事件委托是什么？”的核心思路，并能把它用于实际开发或面试表达。 ==事件委托本质上是利用了浏览器事件冒泡的机制。因为事件在冒泡过程中会上传到父节点，并且父节点可以通过事件对象获取到目标节点，因此可以把子节点的监听函数定义在父节点上，由父节点的监听函数统一处理多个子元素的事件，这种方式称为事件 代理。====== ==使用事件代理我们可以不必要为每一个子元素都绑定一个监听事件，这样减少了内存上的消耗。并且使用事件代理我们还可以实现事件的动态绑定，比如说新增了一个子节点，我们并不需要单独地为它添加一个监听事件，它所发生的事件会交给父元素中的监听函数来处理。== > 来自 <"),e("a",{href:"https://github.com/CavsZhouyou/Front-End-Interview-Notebook/blob/master/JavaScript/JavaScript.md",target:"_blank",rel:"noreferrer"},"https://github.com/CavsZhouyou/Front-End-Interview-Notebook/blob/master/JavaScript/JavaScript.md"),t(">")])])],-1)])])}const u=o(n,[["render",i]]);export{m as __pageData,u as default};
